item.aggregated_output:
// Ordinal model of momentary mood (1 Sad, 2 Meh, 3 Happy).
//
//   P(y_i <= k) = logistic(c_k - eta_i),  k = 1, 2
//   eta_i = time_of_day[s] + weekday[w] + x_d' beta + u_d
//   u_d = phi * u_(d-1) + sigma * e_d          latent daily mood, stationary AR(1)
//
// phi lies in (-1, 1) with (phi + 1) / 2 ~ Beta(2, 2), a prior symmetric around
// zero, so the direction of day-to-day carry-over is estimated, not assumed.
//
// Predictors are standardized; missing cells are imputed as N(0, 1) parameters
// (missing at random). beta = tau * beta_z is a hierarchical shrinkage prior.
data {
  int<lower=1> N;                                 // reports
  int<lower=1> D;                                 // calendar days from first to last report
  int<lower=1> R;                                 // days with reports (rows of X)
  int<lower=0> P;                                 // predictors
  array[N] int<lower=1, upper=3> y;
  array[N] int<lower=1, upper=3> slot;            // morning, afternoon, evening
  array[N] int<lower=1, upper=7> weekday;         // 1 = Monday
  array[N] int<lower=1, upper=D> day;
  array[N] int<lower=1, upper=R> rated_day;       // row of X for each report
  matrix[R, P] X;                                 // missing cells hold 0
  int<lower=0> M;
  array[M] int<lower=1, upper=R> miss_row;
  array[M] int<lower=1, upper=P> miss_col;
  real<lower=0> prior_scale;
}
parameters {
  ordered[2] cutpoints;
  sum_to_zero_vector[3] time_of_day;
  sum_to_zero_vector[7] weekday_effect;
  real<lower=-1, upper=1> phi;
  real<lower=0> sigma_day;
  vector[D] z_day;
  real<lower=0> tau;
  vector[P] beta_z;
  vector[M] x_missing;
}
transformed parameters {
  vector[P] beta = tau * beta_z;
  // Non-centered AR(1), started from its stationary distribution.
  vector[D] mood_day;
  mood_day[1] = sigma_day * z_day[1] / sqrt(1 - square(phi));
  for (d in 2:D) {
    mood_day[d] = phi * mood_day[d - 1] + sigma_day * z_day[d];
  }
}
model {
  vector[N] eta = time_of_day[slot] + weekday_effect[weekday] + mood_day[day];
  if (P > 0) {
    matrix[R, P] X_full = X;
    for (m in 1:M) {
      X_full[miss_row[m], miss_col[m]] = x_missing[m];
    }
    eta += (X_full * beta)[rated_day];
  }
  cutpoints ~ normal([-1, 1]', 1.5);
  // On a sum-to-zero vector this matches PyMC's ZeroSumNormal(0.5).
  time_of_day ~ normal(0, 0.5);
  weekday_effect ~ normal(0, 0.5);
  target += beta_lpdf((phi + 1) / 2 | 2, 2);
  sigma_day ~ normal(0, 1);
  z_day ~ std_normal();
  tau ~ normal(0, prior_scale);
  beta_z ~ std_normal();
  x_missing ~ std_normal();
  y ~ ordered_logistic(eta, cutpoints);
}
# Bayesian ordinal model of momentary mood: data preparation, fitting, summaries.
# These functions only read the database; refit.R turns their output into JSON
# for the web app, which is the only writer.

MODEL_VERSION <- "ordinal-ar1-stan-v3"
SLOTS <- c("morning", "afternoon", "evening")
WEEKDAYS <- c("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
MOODS <- c("Sad", "Meh", "Happy")
MIN_RATED_DAYS <- 14
MIN_RATINGS <- 30
MAX_MISSING <- 0.5 # drop a predictor missing on more than half of the rated days
MIN_OBSERVED <- 10

predictor <- function(field, label, unit, unit_label, lag = 0L) {
  data.frame(field = field, label = label, unit = unit, unit_label = unit_label, lag = lag)
}

# Only information available before the day's reports: last night's sleep and
# physiology, yesterday's behavior (lag 1), and same-day context mood cannot cause.
PREDICTORS <- rbind(
  predictor("sleep_hours", "Sleep last night", 1, "per extra hour"),
  predictor("sleep_efficiency", "Sleep efficiency", 10, "per 10 points"),
  predictor("hrv_ms", "Overnight HRV", 10, "per 10 ms"),
  predictor("resting_hr", "Resting heart rate", 5, "per 5 bpm"),
  predictor("skin_temp_dev_c", "Skin temperature deviation", 0.5, "per 0.5 °C"),
  predictor("steps", "Steps yesterday", 1000, "per 1,000 steps", 1L),
  predictor("exercise_min", "Exercise yesterday", 30, "per 30 min", 1L),
  predictor("outdoor_min", "Time outdoors yesterday", 30, "per 30 min", 1L),
  predictor("social_min", "Time with people yesterday", 60, "per hour", 1L),
  predictor("screen_time_min", "Screen time yesterday", 60, "per hour", 1L),
  predictor("social_media_min", "Social media yesterday", 30, "per 30 min", 1L),
  predictor("caffeine_mg", "Caffeine yesterday", 100, "per 100 mg", 1L),
  predictor("alcohol_units", "Alcohol yesterday", 1, "per drink", 1L),
  predictor("work_day", "Work day", 1, "work day vs. day off"),
  predictor("travel", "Traveling", 1, "away vs. home"),
  predictor("sick", "Sick", 1, "sick vs. well"),
  predictor("temp_mean_c", "Temperature", 5, "per 5 °C"),
  predictor("precipitation_mm", "Precipitation", 5, "per 5 mm"),
  predictor("sunshine_hours", "Sunshine", 1, "per hour"),
  predictor("daylight_hours", "Day length", 1, "per hour"),
  predictor("pm25", "Outdoor PM2.5", 10, "per 10 µg/m³")
)

not_enough_data <- function(message) {
  stop(structure(class = c("not_enough_data", "error", "condition"), list(message = message, call = NULL)))
}

pop_sd <- function(x) {
  x <- x[!is.na(x)]
  sqrt(mean((x - mean(x))^2))
}

iso_weekday <- function(dates) as.integer(format(dates, "%u")) # 1 = Monday

load_dataset <- function(con, user_id) {
  ratings <- DBI::dbGetQuery(
    con, "SELECT rating, slot, study_date FROM ratings WHERE user_id = ? ORDER BY recorded_at",
    params = list(user_id)
  )
  if (nrow(ratings) == 0) not_enough_data("No ratings yet.")
  ratings$study_date <- as.Date(ratings$study_date)
  first <- min(ratings$study_date)
  last <- max(ratings$study_date)
  rated_dates <- sort(unique(ratings$study_date))
  if (length(rated_dates) < MIN_RATED_DAYS || nrow(ratings) < MIN_RATINGS) {
    not_enough_data(sprintf(
      "The model starts after %d ratings on %d different days (so far: %d ratings on %d days).",
      MIN_RATINGS, MIN_RATED_DAYS, nrow(ratings), length(rated_dates)
    ))
  }

  logs <- DBI::dbGetQuery(
    con,
    sprintf(
      "SELECT date, %s FROM daily_logs WHERE user_id = ? AND date BETWEEN ? AND ?",
      paste(PREDICTORS$field, collapse = ", ")
    ),
    params = list(user_id, format(first - 1), format(last))
  )
  # One row per calendar day from the day before the first report, so shifting
  # by one row is exactly a one-day lag.
  frame_dates <- seq(first - 1, last, by = "day")
  frame <- matrix(NA_real_, length(frame_dates), nrow(PREDICTORS), dimnames = list(NULL, PREDICTORS$field))
  rows <- match(as.Date(logs$date), frame_dates)
  for (f in PREDICTORS$field) frame[rows, f] <- as.numeric(logs[[f]])
  rated_rows <- match(rated_dates, frame_dates)

  kept <- integer(0)
  columns <- list()
  next_values <- numeric(0)
  dropped <- list()
  for (j in seq_len(nrow(PREDICTORS))) {
    p <- PREDICTORS[j, ]
    values <- frame[, p$field]
    lagged <- if (p$lag == 1) c(NA, head(values, -1)) else values
    on_rated <- lagged[rated_rows]
    observed <- !is.na(on_rated)
    if (mean(observed) < 1 - MAX_MISSING || sum(observed) < MIN_OBSERVED) {
      reason <- sprintf("recorded on %.0f%% of rated days", 100 * mean(observed))
      dropped[[length(dropped) + 1]] <- list(field = p$field, label = p$label, reason = reason)
    } else if (pop_sd(on_rated) == 0) {
      dropped[[length(dropped) + 1]] <- list(field = p$field, label = p$label, reason = "never varies")
    } else {
      kept <- c(kept, j)
      columns[[length(columns) + 1]] <- on_rated
      # Tomorrow's lag-1 value is known today; same-day values are not.
      next_values <- c(next_values, if (p$lag == 1) values[length(values)] else NA_real_)
    }
  }

  raw <- if (length(columns)) do.call(cbind, columns) else matrix(numeric(0), length(rated_dates), 0)
  means <- if (length(columns)) colMeans(raw, na.rm = TRUE) else numeric(0)
  sds <- if (length(columns)) apply(raw, 2, pop_sd) else numeric(0)
  X <- sweep(sweep(raw, 2, means), 2, sds, "/")
  list(
    y = as.integer(ratings$rating),
    slot = match(ratings$slot, SLOTS),
    weekday = iso_weekday(ratings$study_date),
    day = as.integer(ratings$study_date - first) + 1L,
    rated_day = match(ratings$study_date, rated_dates),
    X = X,
    predictors = PREDICTORS[kept, , drop = FALSE],
    means = unname(means),
    sds = unname(sds),
    dates = seq(first, last, by = "day"),
    rated_dates = rated_dates,
    next_x = (next_values - means) / sds,
    dropped = dropped
  )
}

stan_data <- function(ds, prior_scale = 0.5) {
  missing <- which(is.na(ds$X), arr.ind = TRUE)
  X0 <- ds$X
  X0[is.na(X0)] <- 0
  list(
    N = length(ds$y), D = length(ds$dates), R = length(ds$rated_dates), P = ncol(ds$X),
    y = ds$y, slot = ds$slot, weekday = ds$weekday, day = ds$day, rated_day = ds$rated_day,
    X = X0, M = nrow(missing), miss_row = as.array(as.integer(missing[, 1])),
    miss_col = as.array(as.integer(missing[, 2])), prior_scale = prior_scale
  )
}

fit_model <- function(ds, stan_file, stan_dir, seed = 1, chains = 4, iter = 1000, prior_scale = 0.5) {
  dir.create(stan_dir, showWarnings = FALSE, recursive = TRUE)
  # The compiled program lives in the data folder and is rebuilt only when mood.stan changes.
  model <- cmdstanr::cmdstan_model(stan_file, dir = stan_dir, quiet = TRUE)
  model$sample(
    data = stan_data(ds, prior_scale), seed = seed, chains = chains, parallel_chains = chains,
    iter_warmup = iter, iter_sampling = iter, adapt_delta = 0.95, refresh = 0,
    show_messages = FALSE, show_exceptions = FALSE
  )
}

# Draws of a vector or matrix parameter as a draws x elements matrix.
block <- function(draws, name) {
  cols <- grep(paste0("^", name, "\\["), colnames(draws))
  unclass(draws[, cols, drop = FALSE])
}

interval <- function(x) {
  q <- stats::quantile(x, c(0.025, 0.5, 0.975), names = FALSE)
  list(est = round(q[2], 4), lo = round(q[1], 4), hi = round(q[3], 4))
}

evidence <- function(p_positive) {
  p <- max(p_positive, 1 - p_positive)
  if (p >= 0.975) "strong" else if (p >= 0.9) "moderate" else if (p >= 0.75) "weak" else "unclear"
}

# Posterior draws needed by every summary, with the linear predictor rebuilt per draw.
extract_draws <- function(ds, fit) {
  P <- ncol(ds$X)
  vars <- c("cutpoints", "time_of_day", "weekday_effect", "phi", "sigma_day", "mood_day")
  if (P) vars <- c(vars, "beta")
  missing <- which(is.na(ds$X), arr.ind = TRUE)
  if (nrow(missing)) vars <- c(vars, "x_missing")
  dr <- posterior::as_draws_matrix(fit$draws(vars))
  d <- list(
    cut = block(dr, "cutpoints"), tod = block(dr, "time_of_day"), wd = block(dr, "weekday_effect"),
    mood = block(dr, "mood_day"), phi = as.numeric(dr[, "phi"]), sigma = as.numeric(dr[, "sigma_day"]),
    chain = rep(seq_len(fit$num_chains()), each = nrow(dr) / fit$num_chains())
  )
  S <- nrow(dr)
  X0 <- ds$X
  X0[is.na(X0)] <- 0
  if (P) {
    d$beta <- block(dr, "beta")
    d$xb <- d$beta %*% t(X0)
    if (nrow(missing)) {
      x_missing <- block(dr, "x_missing")
      for (m in seq_len(nrow(missing))) {
        r <- missing[m, 1]
        d$xb[, r] <- d$xb[, r] + x_missing[, m] * d$beta[, missing[m, 2]]
      }
    }
  } else {
    d$beta <- matrix(0, S, 0)
    d$xb <- matrix(0, S, length(ds$rated_dates))
  }
  d$eta <- d$tod[, ds$slot] + d$wd[, ds$weekday] + d$mood[, ds$day] + d$xb[, ds$rated_day]
  d
}

# P(Sad), P(Meh), P(Happy) averaged over draws, for a vector of linear predictors (one per draw).
category_probs <- function(eta, cut) {
  below_meh <- stats::plogis(cut[, 1] - eta)
  below_happy <- stats::plogis(cut[, 2] - eta)
  round(c(mean(below_meh), mean(below_happy - below_meh), mean(1 - below_happy)), 3)
}

summarize_fit <- function(ds, fit, seconds = 0) {
  d <- extract_draws(ds, fit)
  c1 <- d$cut[, 1]
  c2 <- d$cut[, 2]
  eta <- d$eta
  p_happy <- stats::plogis(eta - c2) # vectors of length S recycle down the draws
  p_sad <- stats::plogis(c1 - eta)

  predictors <- lapply(seq_len(nrow(ds$predictors)), function(j) {
    p <- ds$predictors[j, ]
    shift <- d$beta[, j] * p$unit / ds$sds[j]
    p_positive <- round(mean(shift > 0), 3)
    list(
      field = p$field, label = p$label, unit_label = p$unit_label, lag = p$lag,
      mean = ds$means[j], sd = ds$sds[j], missing_pct = 100 * mean(is.na(ds$X[, j])),
      odds_ratio = interval(exp(shift)),
      d_happy_pp = interval(100 * rowMeans(stats::plogis(eta + shift - c2) - p_happy)),
      d_sad_pp = interval(100 * rowMeans(stats::plogis(c1 - eta - shift) - p_sad)),
      p_positive = p_positive,
      direction = if (p_positive >= 0.5) "better" else "worse",
      evidence = evidence(p_positive)
    )
  })
  predictors <- predictors[order(-abs(vapply(predictors, function(p) p$d_happy_pp$est, numeric(1))))]

  # P(Happy) if every report had been made at this level, all else as observed.
  adjusted <- function(effect, index, levels) {
    base <- eta - effect[, index]
    lapply(seq_along(levels), function(k) {
      list(level = levels[k], p_happy = interval(rowMeans(stats::plogis(base + effect[, k] - c2))))
    })
  }

  # Smoothed mood per calendar day: P(Happy) at an average time of day.
  day_eta <- d$mood + d$wd[, iso_weekday(ds$dates)]
  rated_cols <- match(ds$rated_dates, ds$dates)
  day_eta[, rated_cols] <- day_eta[, rated_cols] + d$xb
  daily <- stats::plogis(day_eta - c2)

  # Forecast for the day after the last report: one AR(1) step plus known lag-1 predictors.
  set.seed(0)
  S <- length(c1)
  next_day <- max(ds$dates) + 1
  next_x <- ifelse(is.na(ds$next_x), 0, ds$next_x)
  u_next <- d$phi * d$mood[, ncol(d$mood)] + d$sigma * stats::rnorm(S)
  base_next <- u_next + d$wd[, iso_weekday(next_day)] + as.numeric(d$beta %*% next_x)
  forecast <- stats::setNames(lapply(1:3, function(k) category_probs(base_next + d$tod[, k], d$cut)), SLOTS)

  # Posterior predictive check on category frequencies, overall and by slot.
  F1 <- stats::plogis(c1 - eta)
  F2 <- stats::plogis(c2 - eta)
  u <- matrix(stats::runif(length(eta)), nrow(eta))
  replicated <- 1L + (u > F1) + (u > F2)
  groups <- c(list(all = rep(TRUE, length(ds$y))), stats::setNames(lapply(1:3, function(k) ds$slot == k), SLOTS))
  ppc <- list()
  for (name in names(groups)) {
    mask <- groups[[name]]
    if (!any(mask)) next
    shares <- sapply(1:3, function(k) rowMeans(replicated[, mask, drop = FALSE] == k))
    ppc[[name]] <- list(
      observed = round(tabulate(ds$y[mask], 3) / sum(mask), 3),
      predicted = round(colMeans(shares), 3),
      lo = round(apply(shares, 2, stats::quantile, 0.05, names = FALSE), 3),
      hi = round(apply(shares, 2, stats::quantile, 0.95, names = FALSE), 3)
    )
  }

  # Pointwise log likelihood for PSIS-LOO.
  lik <- F1
  lik[, ds$y == 2] <- (F2 - F1)[, ds$y == 2]
  lik[, ds$y == 3] <- (1 - F2)[, ds$y == 3]
  log_lik <- log(pmax(lik, 1e-300))
  loo_fit <- suppressWarnings(loo::loo(log_lik, r_eff = loo::relative_eff(exp(log_lik), chain_id = d$chain)))

  vars <- c("cutpoints", "time_of_day", "weekday_effect", "phi", "sigma_day", "tau")
  if (ncol(ds$X)) vars <- c(vars, "beta")
  diag <- posterior::summarise_draws(fit$draws(vars), "rhat", "ess_bulk", "ess_tail")
  diagnostics <- list(
    max_rhat = max(diag$rhat, na.rm = TRUE),
    min_ess_bulk = min(diag$ess_bulk, na.rm = TRUE),
    min_ess_tail = min(diag$ess_tail, na.rm = TRUE),
    divergences = sum(fit$diagnostic_summary(quiet = TRUE)$num_divergent),
    elpd_loo = loo_fit$estimates["elpd_loo", "Estimate"],
    elpd_loo_se = loo_fit$estimates["elpd_loo", "SE"],
    p_loo = loo_fit$estimates["p_loo", "Estimate"],
    high_pareto_k = sum(loo_fit$diagnostics$pareto_k > 0.7)
  )
  diagnostics$converged <- diagnostics$max_rhat < 1.01 && diagnostics$min_ess_bulk > 400 && diagnostics$divergences == 0

  list(
    model = list(
      version = MODEL_VERSION, draws = S, chains = fit$num_chains(), seconds = round(seconds, 1),
      software = list(
        r = R.version.string, cmdstan = cmdstanr::cmdstan_version(),
        cmdstanr = as.character(utils::packageVersion("cmdstanr")),
        posterior = as.character(utils::packageVersion("posterior")),
        loo = as.character(utils::packageVersion("loo"))
      )
    ),
    data = list(
      n_ratings = length(ds$y), n_rated_days = length(ds$rated_dates),
      first_date = format(min(ds$dates)), last_date = format(max(ds$dates)), counts = tabulate(ds$y, 3)
    ),
    predictors = predictors,
    dropped = ds$dropped,
    time_of_day = adjusted(d$tod, ds$slot, SLOTS),
    weekday = adjusted(d$wd, ds$weekday, WEEKDAYS),
    # p_positive is the posterior probability of carry-over (hypothesis 5).
    dynamics = list(phi = c(interval(d$phi), p_positive = round(mean(d$phi > 0), 4)), sigma_day = interval(d$sigma)),
    daily_mood = list(
      dates = format(ds$dates),
      mean = round(colMeans(daily), 3),
      lo = round(apply(daily, 2, stats::quantile, 0.1, names = FALSE), 3),
      hi = round(apply(daily, 2, stats::quantile, 0.9, names = FALSE), 3)
    ),
    forecast = list(date = format(next_day), slots = forecast),
    ppc = ppc,
    diagnostics = diagnostics
  )
}

# Thinned draws the web app uses for what-if predictions without calling R.
whatif_draws <- function(ds, fit, keep = 1000) {
  d <- extract_draws(ds, fit)
  S <- length(d$phi)
  i <- unique(round(seq(1, S, length.out = min(S, keep))))
  list(
    cutpoints = d$cut[i, , drop = FALSE], time_of_day = d$tod[i, , drop = FALSE],
    weekday_effect = d$wd[i, , drop = FALSE], beta = d$beta[i, , drop = FALSE],
    phi = d$phi[i], sigma_day = d$sigma[i],
    fields = I(ds$predictors$field), means = I(ds$means), sds = I(ds$sds)
  )
}

# P(Happy) with vs. without each tag, from Beta(1, 1) posteriors. Same-moment
# associations: a tag can be a cause of mood or a consequence of it.
tag_associations <- function(con, user_id, min_uses = 5, draws = 4000) {
  r <- DBI::dbGetQuery(con, "SELECT rating, tags FROM ratings WHERE user_id = ?", params = list(user_id))
  if (!nrow(r)) return(list())
  tags <- lapply(r$tags, function(t) unique(as.character(jsonlite::fromJSON(t))))
  uses <- sort(table(unlist(tags)), decreasing = TRUE)
  happy <- r$rating == 3
  set.seed(0)
  out <- list()
  for (tag in names(uses)[uses >= min_uses]) {
    has <- vapply(tags, function(t) tag %in% t, logical(1))
    if (all(has)) next
    p_with <- stats::rbeta(draws, 1 + sum(happy[has]), 1 + sum(has) - sum(happy[has]))
    p_without <- stats::rbeta(draws, 1 + sum(happy[!has]), 1 + sum(!has) - sum(happy[!has]))
    diff <- interval(100 * (p_with - p_without))
    out[[length(out) + 1]] <- list(
      tag = tag, n = sum(has), p_with = round(stats::median(p_with), 4),
      p_without = round(stats::median(p_without), 4), est = diff$est, lo = diff$lo, hi = diff$hi,
      p_positive = round(mean(p_with > p_without), 3)
    )
  }
  out
}

// Runs the R analysis and stores what it returns. R reads the database and
// writes JSON; this module is the only one that records runs.
import { execFile } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync } from "node:fs";
import path from "node:path";
import { promisify } from "node:util";
import { sha256 } from "./auth.ts";
import { DATA_DIR, DB_PATH, ROOT, RSCRIPT } from "./config.ts";
import { all, get, nowIso, run, transaction } from "./db.ts";
import { SLOTS, type Slot } from "./study.ts";

const execFileAsync = promisify(execFile);
const ANALYSIS_DIR = path.join(ROOT, "analysis");
const KEEP_FULL_RUNS = 10; // older runs keep only their effect estimates
const RUN_TIMEOUT_MS = 30 * 60 * 1000;
const STALE_MS = 2 * 3600 * 1000;

export type Status = "running" | "done" | "waiting" | "failed";

interface RunRow {
  id: number;
  user_id: number;
  status: Status;
  started_at: string;
  finished_at: string | null;
  n_ratings: number;
  n_days: number;
  data_fingerprint: string;
  results: string;
  message: string;
}

// The results JSON written by analysis/mood.R; see summarize_fit() there for its shape.
export type Results = Record<string, any>;
export type Run = Omit<RunRow, "results"> & { results: Results };

const parse = (row: RunRow | undefined): Run | null => (row ? { ...row, results: JSON.parse(row.results) as Results } : null);

export const getRun = (id: number): Run | null => parse(get<RunRow>("SELECT * FROM analysis_runs WHERE id = ?", id));
export const latestRun = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? ORDER BY id DESC LIMIT 1", userId));
export const latestDone = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? AND status = 'done' ORDER BY id DESC LIMIT 1", userId));
/** The newest finished run of any kind: tag comparisons exist even before the model can run. */
export const latestFinished = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? AND status IN ('done', 'waiting') ORDER BY id DESC LIMIT 1", userId));
export const recentRuns = (userId: number, limit = 10) =>
  all<Omit<RunRow, "results">>(
    "SELECT id, user_id, status, started_at, finished_at, n_ratings, n_days, data_fingerprint, message FROM analysis_runs WHERE user_id = ? ORDER BY id DESC LIMIT ?",
    userId, limit,
  );

export const drawsPath = (runId: number): string => path.join(DATA_DIR, "posteriors", `run_${runId}.json`);

/** Changes whenever the data or the analysis code change, so hourly runs can skip. */
export function fingerprint(userId: number): string {
  const ratings = get("SELECT count(*) AS n, max(created_at) AS t FROM ratings WHERE user_id = ?", userId);
  const logs = get("SELECT count(*) AS n, max(updated_at) AS t FROM daily_logs WHERE user_id = ?", userId);
  const code = ["mood.R", "mood.stan", "refit.R"].map((f) => readFileSync(path.join(ANALYSIS_DIR, f), "utf8"));
  return sha256(JSON.stringify([ratings, logs, code]));
}

/** A run still marked running after two hours was killed midway. */
export function markInterrupted(): void {
  run(
    "UPDATE analysis_runs SET status = 'failed', message = 'Interrupted before it finished.', finished_at = ? WHERE status = 'running' AND started_at < ?",
    nowIso(), new Date(Date.now() - STALE_MS).toISOString(),
  );
}

/** Fit the model for one user. Returns the run, or null when skipped. */
export async function refitUser(userId: number, options: { ifNewData?: boolean } = {}): Promise<Run | null> {
  const dataFingerprint = fingerprint(userId);
  const runId = transaction(() => {
    if (get("SELECT 1 FROM analysis_runs WHERE user_id = ? AND status = 'running'", userId)) return null;
    const last = get<{ data_fingerprint: string }>(
      "SELECT data_fingerprint FROM analysis_runs WHERE user_id = ? AND status != 'running' ORDER BY id DESC LIMIT 1", userId,
    );
    if (options.ifNewData && last?.data_fingerprint === dataFingerprint) return null;
    return Number(run("INSERT INTO analysis_runs (user_id, status, data_fingerprint) VALUES (?, 'running', ?)", userId, dataFingerprint).lastInsertRowid);
  });
  if (runId === null) return null;

  const out = path.join(DATA_DIR, "tmp", `run_${runId}.json`);
  mkdirSync(path.dirname(out), { recursive: true });
  mkdirSync(path.dirname(drawsPath(runId)), { recursive: true });
  try {
    await execFileAsync(
      RSCRIPT,
      [
        path.join(ANALYSIS_DIR, "refit.R"), "--db", DB_PATH, "--user", String(userId), "--out", out,
        "--draws", drawsPath(runId), "--stan-dir", path.join(DATA_DIR, "stan"), "--seed", String(runId),
      ],
      { timeout: RUN_TIMEOUT_MS, maxBuffer: 16 * 1024 * 1024 },
    );
    const output = JSON.parse(readFileSync(out, "utf8")) as { status: Status; message?: string; results?: Results };
    const results = output.results ?? {};
    run(
      "UPDATE analysis_runs SET status = ?, message = ?, results = ?, n_ratings = ?, n_days = ?, finished_at = ? WHERE id = ?",
      output.status, output.message ?? "", JSON.stringify(results), results.data?.n_ratings ?? 0, results.data?.n_rated_days ?? 0, nowIso(), runId,
    );
  } catch (error) {
    const stderr = String((error as { stderr?: unknown }).stderr ?? "");
    const lines = stderr.split("\n").filter((l) => l.trim() && !l.includes("built under R version"));
    const message = (lines.slice(-3).join(" ") || String(error)).slice(0, 500);
    run("UPDATE analysis_runs SET status = 'failed', message = ?, finished_at = ? WHERE id = ?", message, nowIso(), runId);
  } finally {
    rmSync(out, { force: true });
  }
  prune(userId);
  return getRun(runId);
}

/** Drop bulky series and posterior draws from older runs. */
function prune(userId: number): void {
  const old = all<{ id: number; results: string }>(
    "SELECT id, results FROM analysis_runs WHERE user_id = ? AND status = 'done' ORDER BY id DESC LIMIT -1 OFFSET ?",
    userId, KEEP_FULL_RUNS,
  );
  for (const row of old) {
    rmSync(drawsPath(row.id), { force: true });
    const results = JSON.parse(row.results) as Results;
    if ("daily_mood" in results) {
      for (const key of ["daily_mood", "ppc", "forecast"]) delete results[key];
      run("UPDATE analysis_runs SET results = ? WHERE id = ?", JSON.stringify(results), row.id);
    }
  }
}

interface Draws {
  cutpoints: number[][];
  time_of_day: number[][];
  weekday_effect: number[][];
  beta: number[][];
  phi: number[];
  sigma_day: number[];
  fields: string[];
  means: number[];
  sds: number[];
}

/** Deterministic standard normals (mulberry32 plus Box-Muller), so answers do not jitter. */
function normals(seed: number): () => number {
  let a = seed >>> 0;
  const uniform = () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return () => Math.sqrt(-2 * Math.log(1 - uniform())) * Math.cos(2 * Math.PI * uniform());
}

const logistic = (x: number): number => 1 / (1 + Math.exp(-x));

/**
 * P(Sad, Meh, Happy) per slot on a typical day with the given predictor values
 * (blank means your average). The latent daily mood is averaged over its
 * long-run distribution, so this describes a typical day, not tomorrow.
 */
export function whatIf(runId: number, values: Record<string, string>, weekday: number): Record<Slot, number[]> {
  const file = drawsPath(runId);
  if (!existsSync(file)) throw new Error("The saved posterior for this run is gone; refit first.");
  const d = JSON.parse(readFileSync(file, "utf8")) as Draws;
  const x = d.fields.map((field, j) => {
    const raw = values[field]?.trim();
    if (!raw) return 0;
    const n = Number(raw);
    if (!Number.isFinite(n)) throw new RangeError("Please enter numbers only.");
    return (n - d.means[j]) / d.sds[j];
  });
  const z = normals(1);
  const totals = SLOTS.map(() => [0, 0, 0]);
  for (let s = 0; s < d.phi.length; s++) {
    const stationarySd = d.sigma_day[s] / Math.sqrt(1 - d.phi[s] ** 2);
    const base = x.reduce((sum, xj, j) => sum + d.beta[s][j] * xj, 0) + d.weekday_effect[s][weekday] + stationarySd * z();
    SLOTS.forEach((_, k) => {
      const eta = base + d.time_of_day[s][k];
      const belowMeh = logistic(d.cutpoints[s][0] - eta);
      const belowHappy = logistic(d.cutpoints[s][1] - eta);
      totals[k][0] += belowMeh;
      totals[k][1] += belowHappy - belowMeh;
      totals[k][2] += 1 - belowHappy;
    });
  }
  const round = (v: number) => Math.round((v / d.phi.length) * 1000) / 1000;
  return Object.fromEntries(SLOTS.map((slot, k) => [slot, totals[k].map(round)])) as Record<Slot, number[]>;
}
