import type { Run } from "./analysis.ts";
import {
  BACKUP_DIR, BACKUP_GPG_RECIPIENT, BACKUP_KEEP, DATA_DIR, PUBLISH_DIR, PUBLISH_SUBDIR, ROOT,
  WEATHER_LATITUDE, WEATHER_LONGITUDE,
} from "./config.ts";
