    if (p.evidence !== "strong" && p.evidence !== "moderate") return "neutral";
    return p.direction === "better" ? "pos" : "neg";
  }

  function cell(row, text, cls) {
    const td = document.createElement("td");
    if (cls) td.className = cls;
    td.textContent = text;
    row.appendChild(td);
    return td;
  }

  function render(r) {
