  9	const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;
 10	
 11	export function isTimeZone(name: unknown): name is string {
 12	  if (typeof name !== "string" || !name) return false;
 13	  try {
 14	    new Intl.DateTimeFormat("en-US", { timeZone: name });
 15	    return true;
 16	  } catch {
 17	    return false;
 18	  }
 19	}
