 21	/**
 22	 * Map an instant to its study date and slot in a time zone. The study day starts
 23	 * at dayStartHour, so a report at 1 AM belongs to the previous day's evening.
 24	 */
 25	export function studyDayAndSlot(instant: Date, timeZone: string, dayStartHour = 4): { studyDate: string; slot: Slot } {
 26	  const parts = new Intl.DateTimeFormat("en-US", {
 27	    timeZone, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", hourCycle: "h23",
 28	  }).formatToParts(instant);
 29	  const part = (type: string) => Number(parts.find((p) => p.type === type)?.value);
 30	  const hour = part("hour");
 31	  const slot: Slot = hour >= dayStartHour && hour < 12 ? "morning" : hour >= 12 && hour < 18 ? "afternoon" : "evening";
 32	  let day = Date.UTC(part("year"), part("month") - 1, part("day"));
 33	  if (hour < dayStartHour) day -= 24 * 3600 * 1000;
 34	  return { studyDate: new Date(day).toISOString().slice(0, 10), slot };
 35	}
 36	
 37	export const addDays = (isoDate: string, days: number): string =>
 38	  new Date(Date.parse(`${isoDate}T00:00:00Z`) + days * 24 * 3600 * 1000).toISOString().slice(0, 10);
 39	
 40	/** 0 = Monday. */
 41	export const weekdayIndex = (isoDate: string): number => (new Date(`${isoDate}T00:00:00Z`).getUTCDay() + 6) % 7;
