 43	const TAG = /^[\p{L}\p{N}_-]{1,30}$/u;
 44	
 45	/** Lowercase, deduplicated tags from an explicit list plus #hashtags in the note. */
 46	export function normalizeTags(tags: unknown, note: string): string[] {
 47	  const listed = Array.isArray(tags) ? tags.map((t) => String(t).trim().replace(/^#/, "").toLowerCase()) : [];
 48	  const inNote = [...note.matchAll(/#([\p{L}\p{N}_-]{1,30})/gu)].map((m) => m[1].toLowerCase());
 49	  return [...new Set([...listed, ...inNote])].filter((t) => TAG.test(t)).slice(0, 10);
 50	}
