 64	export function validateRating(body: Record<string, unknown>, now = new Date()): { value?: RatingInput; errors?: Errors } {
 65	  const errors: Errors = {};
 66	  const rating = Number(body.rating);
 67	  if (![1, 2, 3].includes(rating) || String(body.rating).trim() !== String(rating)) errors.rating = "Must be 1, 2 or 3.";
 68	  let recordedAt = now;
 69	  if (body.recorded_at !== undefined && body.recorded_at !== null && body.recorded_at !== "") {
 70	    recordedAt = new Date(String(body.recorded_at));
 71	    if (Number.isNaN(recordedAt.getTime())) errors.recorded_at = "Not a date and time.";
 72	    else if (recordedAt.getTime() > now.getTime() + MAX_CLOCK_SKEW_MS) errors.recorded_at = "Rating time is in the future.";
 73	    else if (recordedAt.getTime() < now.getTime() - MAX_BACKDATE_MS) errors.recorded_at = "Ratings older than 14 days cannot be sent here.";
 74	  }
 75	  const note = body.note === undefined || body.note === null ? "" : String(body.note);
 76	  if (note.length > 2000) errors.note = "At most 2000 characters.";
 77	  const source = body.source === undefined ? "web" : String(body.source);
 78	  if (!/^[\w-]{1,20}$/.test(source)) errors.source = "Letters, digits, - or _, at most 20.";
 79	  let clientId = body.client_id === undefined || body.client_id === null ? crypto.randomUUID() : String(body.client_id);
 80	  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(clientId)) errors.client_id = "Must be a UUID.";
 81	  clientId = clientId.toLowerCase();
 82	  if (body.tags !== undefined && !Array.isArray(body.tags)) errors.tags = "Must be a list.";
 83	  if (Object.keys(errors).length) return { errors };
 84	  return {
 85	    value: {
 86	      rating: rating as 1 | 2 | 3,
 87	      recordedAt,
 88	      // An unknown zone from an odd browser should not cost a rating; the
 89	      // profile's zone is used instead.
 90	      timeZone: isTimeZone(body.time_zone) ? body.time_zone : null,
 91	      note,
 92	      tags: normalizeTags(body.tags, note),
 93	      source,
 94	      clientId,
 95	    },
 96	  };
 97	}
 98	
 99	export interface FieldSpec {
100	  name: string;
101	  label: string;
102	  type: "float" | "int" | "bool" | "text";
103	  min?: number;
104	  max?: number;
105	  help?: string;
106	}
107	
108	// Must match the daily_logs columns in schema.sql (a test checks this).
109	export const LOG_SECTIONS: { title: string; fields: FieldSpec[] }[] = [
110	  {
111	    title: "Last night",
112	    fields: [
113	      { name: "sleep_hours", label: "Sleep (hours)", type: "float", min: 0, max: 24 },
114	      { name: "sleep_efficiency", label: "Sleep efficiency (%)", type: "float", min: 0, max: 100 },
115	      { name: "hrv_ms", label: "HRV (ms)", type: "float", min: 1, max: 300, help: "Keep one source and metric (RMSSD or SDNN)" },
116	      { name: "resting_hr", label: "Resting heart rate (bpm)", type: "float", min: 25, max: 200 },
117	      { name: "skin_temp_dev_c", label: "Skin temperature deviation (°C)", type: "float", min: -5, max: 5 },
118	    ],
119	  },
120	  {
121	    title: "Today",
122	    fields: [
123	      { name: "steps", label: "Steps", type: "int", min: 0, max: 200000 },
124	      { name: "exercise_min", label: "Exercise (min)", type: "int", min: 0, max: 1440 },
125	      { name: "outdoor_min", label: "Time outdoors (min)", type: "int", min: 0, max: 1440 },
126	      { name: "social_min", label: "Time with people (min)", type: "int", min: 0, max: 1440, help: "In person with friends or family" },
127	      { name: "screen_time_min", label: "Screen time (min)", type: "int", min: 0, max: 1440 },
128	      { name: "social_media_min", label: "Social media (min)", type: "int", min: 0, max: 1440 },
129	      { name: "caffeine_mg", label: "Caffeine (mg)", type: "int", min: 0, max: 2000 },
130	      { name: "alcohol_units", label: "Alcohol (standard drinks)", type: "float", min: 0, max: 50 },
131	    ],
132	  },
133	  {
134	    title: "Context",
135	    fields: [
136	      { name: "work_day", label: "Work day", type: "bool" },
137	      { name: "travel", label: "Away from home", type: "bool" },
138	      { name: "sick", label: "Sick", type: "bool" },
139	    ],
140	  },
141	  {
142	    title: "Evening check-in",
143	    fields: [
144	      { name: "day_satisfaction", label: "Satisfaction with today (0 to 10)", type: "int", min: 0, max: 10, help: "All things considered, how satisfied were you with today?" },
145	      { name: "note", label: "Note", type: "text" },
146	    ],
147	  },
148	  {
149	    title: "Weather (filled in automatically)",
150	    fields: [
151	      { name: "temp_mean_c", label: "Mean temperature (°C)", type: "float", min: -60, max: 60 },
152	      { name: "precipitation_mm", label: "Precipitation (mm)", type: "float", min: 0, max: 500 },
153	      { name: "sunshine_hours", label: "Sunshine (hours)", type: "float", min: 0, max: 24 },
154	      { name: "daylight_hours", label: "Day length (hours)", type: "float", min: 0, max: 24 },
155	      { name: "pm25", label: "PM2.5 (µg/m³)", type: "float", min: 0, max: 1000 },
156	    ],
157	  },
158	];
159	export const DAILY_FIELDS: FieldSpec[] = LOG_SECTIONS.flatMap((s) => s.fields);
160	export const WEATHER_FIELDS = ["temp_mean_c", "precipitation_mm", "sunshine_hours", "daylight_hours", "pm25"];
161	
162	export type DailyValue = number | string | null;
163	
164	function parseField(field: FieldSpec, raw: unknown): { value?: DailyValue; error?: string } {
165	  if (raw === null || raw === undefined || raw === "") return { value: field.type === "text" ? "" : null };
166	  if (field.type === "text") {
167	    const text = String(raw);
168	    return text.length > 2000 ? { error: "At most 2000 characters." } : { value: text };
169	  }
170	  if (field.type === "bool") {
171	    const s = String(raw).toLowerCase();
172	    if (["true", "1", "yes", "on"].includes(s)) return { value: 1 };
173	    if (["false", "0", "no", "off"].includes(s)) return { value: 0 };
174	    return { error: "Must be yes or no." };
175	  }
176	  const n = typeof raw === "number" ? raw : Number(String(raw).trim());
177	  if (!Number.isFinite(n)) return { error: "Must be a number." };
178	  if (field.type === "int" && !Number.isInteger(n)) return { error: "Must be a whole number." };
179	  if ((field.min !== undefined && n < field.min) || (field.max !== undefined && n > field.max)) {
180	    return { error: `Must be between ${field.min} and ${field.max}.` };
181	  }
182	  return { value: n };
183	}
184	
185	/** Validate only the fields present, so partial updates never clear other fields. */
186	export function validateDaily(body: Record<string, unknown>): { date?: string; values?: Record<string, DailyValue>; errors?: Errors } {
187	  const errors: Errors = {};
188	  const date = String(body.date ?? "");
189	  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || Number.isNaN(Date.parse(`${date}T00:00:00Z`))) errors.date = "Required, as YYYY-MM-DD.";
190	  const values: Record<string, DailyValue> = {};
191	  for (const field of DAILY_FIELDS) {
192	    if (!(field.name in body)) continue;
193	    const parsed = parseField(field, body[field.name]);
194	    if (parsed.error) errors[field.name] = parsed.error;
195	    else values[field.name] = parsed.value ?? null;
196	  }
197	  return Object.keys(errors).length ? { errors } : { date, values };
198	}

router.add("POST", "/settings/tokens/:id/revoke/", "session", (req) => {
  run("DELETE FROM device_tokens WHERE id = ? AND user_id = ?", Number(req.params.id), req.user!.id);
  return flashTo(req, "Device token revoked.", "/settings/");
});

router.add("POST", "/settings/delete-all/", "session", (req) => {
  if (req.body.confirm !== "DELETE") return flashTo(req, "Type DELETE to confirm. Nothing was deleted.", "/settings/");
  const userId = req.user!.id;
  for (const { id } of all<{ id: number }>("SELECT id FROM analysis_runs WHERE user_id = ?", userId)) rmSync(drawsPath(id), { force: true });
  transaction(() => {
    for (const table of ["analysis_runs", "ratings", "daily_logs"]) run(`DELETE FROM ${table} WHERE user_id = ?`, userId);
  });
  return flashTo(req, "All reports, daily logs and analyses were deleted. Encrypted backups were kept.", "/settings/");
});

const csvCell = (value: unknown): string => {
  const s = value === null || value === undefined ? "" : String(value);
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const csv = (rows: unknown[][]): string => rows.map((r) => r.map(csvCell).join(",")).join("\r\n") + "\r\n";

